def is_samepatterns(patterns, sequence):
    if len(patterns) != len(sequence):
        return False
    mapping = {}
    used = set()
    for p, s in zip(patterns, sequence):
        if p in mapping:
            if mapping[p] != s:
                return False
        else:
            if s in used:
                return False
            mapping[p] = s
            used.add(s)
    return True
